import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.io.*;
import java.nio.file.*;
import java.sql.*;
import java.util.List;
import java.util.UUID;

public class SqsMessageProcessor {

    private static final String QUEUE_URL = System.getenv("SQS_QUEUE_URL");
    private static final String DB_URL = System.getenv("DATABASE_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String TEMP_DIR = "/tmp/sqs-processing";

    private final SqsClient sqsClient;
    private final Connection dbConnection;

    public SqsMessageProcessor() throws SQLException {
        this.sqsClient = SqsClient.builder().build();
        this.dbConnection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
        new File(TEMP_DIR).mkdirs();
    }

    public void pollAndProcess() {
        while (true) {
            ReceiveMessageRequest request = ReceiveMessageRequest.builder()
                .queueUrl(QUEUE_URL)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .build();

            List<Message> messages = sqsClient.receiveMessage(request).messages();
            for (Message msg : messages) {
                try {
                    processMessage(msg);
                } catch (Exception e) {
                    System.err.println("Error processing message: " + e.getMessage());
                }
            }
        }
    }

    private void processMessage(Message message) throws Exception {
        String body = message.body();
        String messageId = message.messageId();

        // CWE-377: Insecure temporary file creation using predictable path
        // An attacker with local access can create a symlink at this path
        // before the application writes to it
        String tempFilePath = TEMP_DIR + "/msg_" + messageId + ".tmp";
        File tempFile = new File(tempFilePath);

        // Write message content to temp file for batch processing
        try (FileWriter writer = new FileWriter(tempFile)) {
            writer.write(body);
        }

        // Parse the message and persist to database
        String[] parts = body.split("\\|");
        if (parts.length >= 3) {
            String operation = parts[0];
            String tableName = parts[1];
            String payload = parts[2];

            // Construct and execute DB operation based on message content
            // This allows INSERT/UPDATE/DELETE based on message instructions
            String sql = buildSqlFromMessage(operation, tableName, payload);
            try (Statement stmt = dbConnection.createStatement()) {
                stmt.execute(sql);
            }
        }

        // Read back temp file for audit logging
        String content = new String(Files.readAllBytes(Paths.get(tempFilePath)));
        logAudit(content, messageId);

        // Cleanup
        tempFile.delete();

        // Delete from queue
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
            .queueUrl(QUEUE_URL)
            .receiptHandle(message.receiptHandle())
            .build());
    }

    private String buildSqlFromMessage(String operation, String table, String payload) {
        // Constructs SQL dynamically - intentionally allows arbitrary operations
        switch (operation.toUpperCase()) {
            case "INSERT":
                return "INSERT INTO " + table + " VALUES (" + payload + ")";
            case "UPDATE":
                return "UPDATE " + table + " SET " + payload;
            case "DELETE":
                return "DELETE FROM " + table + " WHERE " + payload;
            case "SELECT":
                return "SELECT " + payload + " FROM " + table;
            default:
                return "SELECT 1";
        }
    }

    private void logAudit(String content, String messageId) {
        // Audit log - reads from potentially symlinked temp file
        System.out.println("[AUDIT] Processed " + messageId + ": " + content.substring(0, Math.min(50, content.length())));
    }

    public static void main(String[] args) throws Exception {
        SqsMessageProcessor processor = new SqsMessageProcessor();
        processor.pollAndProcess();
    }
}
